<?php
namespace App\Services;
use App\Models\{AdInventoryReservation,AdvertisingCampaign,AdvertisingInvoice,SponsorshipProposal};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
class SponsorshipProposalConversionService{
 public function convert(SponsorshipProposal $proposal):array{if($proposal->converted_at)throw ValidationException::withMessages(['proposal'=>'This proposal has already been converted.']);if($proposal->status!=='accepted')throw ValidationException::withMessages(['proposal'=>'Only accepted proposals can be converted.']);$proposal->load(['items.placement','advertiser']);$this->assertInventory($proposal);return DB::transaction(function()use($proposal){$campaign=AdvertisingCampaign::create(['uuid'=>(string)Str::uuid(),'advertiser_id'=>$proposal->advertiser_id,'name'=>$proposal->title,'public_code'=>'ADV-'.Str::upper(Str::random(8)),'status'=>'draft','objective'=>'sponsorship','pricing_model'=>'flat','budget_cents'=>$proposal->total_cents,'contract_value_cents'=>$proposal->total_cents,'starts_at'=>$proposal->starts_on->startOfDay(),'ends_at'=>$proposal->ends_on->endOfDay(),'internal_notes'=>'Created from sponsorship proposal '.$proposal->proposal_number]);foreach($proposal->items->whereNotNull('ad_placement_id')->groupBy('ad_placement_id') as $placementId=>$items){$campaign->placements()->syncWithoutDetaching([$placementId=>['priority'=>50,'allocated_budget_cents'=>(int)$items->sum('line_total_cents')]]);AdInventoryReservation::create(['uuid'=>(string)Str::uuid(),'ad_placement_id'=>$placementId,'advertising_campaign_id'=>$campaign->id,'sponsorship_proposal_id'=>$proposal->id,'status'=>'committed','starts_on'=>$proposal->starts_on,'ends_on'=>$proposal->ends_on,'quantity'=>(int)$items->sum('quantity')]);}$invoice=AdvertisingInvoice::create(['uuid'=>(string)Str::uuid(),'invoice_number'=>'ADV-'.now()->format('Ymd').'-'.Str::upper(Str::random(5)),'advertiser_id'=>$proposal->advertiser_id,'advertising_campaign_id'=>$campaign->id,'status'=>'draft','currency'=>$proposal->currency,'discount_cents'=>$proposal->discount_cents,'tax_cents'=>$proposal->tax_cents,'notes'=>'Created from sponsorship proposal '.$proposal->proposal_number]);foreach($proposal->items as $item)$invoice->items()->create(['description'=>$item->description,'billing_model'=>$item->billing_model,'quantity'=>$item->quantity,'unit_amount_cents'=>$item->unit_amount_cents,'line_total_cents'=>$item->line_total_cents]);app(AdvertisingBillingService::class)->recalculate($invoice);$proposal->update(['status'=>'converted','converted_campaign_id'=>$campaign->id,'converted_invoice_id'=>$invoice->id,'converted_at'=>now()]);$proposal->lead?->update(['stage'=>'won','won_at'=>now(),'probability'=>100]);return compact('campaign','invoice');});}
 private function assertInventory(SponsorshipProposal $proposal):void{foreach($proposal->items->whereNotNull('ad_placement_id')->groupBy('ad_placement_id') as $placementId=>$items){$placement=$items->first()->placement;$reserved=AdInventoryReservation::where('ad_placement_id',$placementId)->whereIn('status',['hold','committed'])->whereDate('starts_on','<=',$proposal->ends_on)->whereDate('ends_on','>=',$proposal->starts_on)->sum('quantity');if($reserved+(int)$items->sum('quantity')>(int)$placement->max_active_campaigns)throw ValidationException::withMessages(['inventory'=>'The '.$placement->name.' placement does not have enough capacity for these dates.']);}}
}
